<script setup lang="ts">
// PT-05; FR-ASSET-001/002/004; D18-API-012..014/046..049; TC-ASSET-003/004/005/008
import {ref,reactive,computed,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {useAuthStore} from '../../stores/auth';import {get,command,errorText,type Row,type Page} from '../../api/implemented';import {classifications,assetStates,dataTypes,sensitivities,type Asset,type Field,type Source} from '../../api/asset';
const route=useRoute(),auth=useAuthStore(),send=command();const asset=ref<Asset|null>(null),fields=ref<Field[]>([]),owners=ref<Row[]>([]),sources=ref<Source[]>([]),error=ref(''),message=ref(''),busy=ref(false),showEdit=ref(false),showField=ref(false),selected=ref<Field|null>(null),reason=ref('');
const edit=reactive({name:'',classification:'INTERNAL',ownerId:'',sourceId:'',reason:''});const field=reactive({fieldCode:'',displayName:'',dataType:'VARCHAR',nullable:false,sensitiveLevel:'LOW',reason:''});const canWrite=computed(()=>auth.permissions.includes('asset:write'));const linked=computed(()=>selected.value&&((selected.value.ruleCount||0)+(selected.value.standardCount||0)+(selected.value.issueCount||0)>0));
async function load(){const id=route.query.asset;if(typeof id!=='string'){asset.value=null;return}asset.value=await get<Asset>('D18-API-012',{id});fields.value=await get<Field[]>('D18-API-013',{id});if(canWrite.value){sources.value=(await get<Page>('D18-API-050',{}, {orgId:asset.value.orgId,status:'ENABLED',size:'100'})).items as Source[];if(auth.permissions.includes('auth:read'))owners.value=(await get<Page>('D18-API-007',{}, {orgId:asset.value.orgId,status:'ENABLED',size:'100'})).items}}
async function run(f:()=>Promise<unknown>){busy.value=true;error.value='';message.value='';try{await f()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function openEdit(){if(!asset.value)return;Object.assign(edit,{name:asset.value.name,classification:asset.value.classification,ownerId:asset.value.ownerId||'',sourceId:asset.value.sourceId||'',reason:''});showEdit.value=true}
async function save(){if(!asset.value)return;await send('D18-API-046',{id:asset.value.id},{...edit,ownerId:edit.ownerId||null,sourceId:edit.sourceId||null,expectedVersion:asset.value.version});showEdit.value=false;await load();message.value='资产信息已保存'}
async function state(next:'publish'|'disable'){if(!asset.value)return;await send(next==='publish'?'D18-API-047':'D18-API-048',{id:asset.value.id},{expectedVersion:asset.value.version,reason:reason.value});reason.value='';await load();message.value=next==='publish'?'资产已发布':'资产已停用，历史记录保留'}
function openField(f:Field|null){selected.value=f;Object.assign(field,{fieldCode:f?.fieldCode||'',displayName:f?.displayName||'',dataType:f?.dataType||'VARCHAR',nullable:Boolean(f?.nullable),sensitiveLevel:f?.sensitiveLevel||'LOW',reason:''});showField.value=true}
async function saveField(){if(!asset.value)return;const common={displayName:field.displayName,dataType:field.dataType,nullable:field.nullable,sensitiveLevel:field.sensitiveLevel,expectedAssetVersion:asset.value.version};if(selected.value)await send('D18-API-049',{id:asset.value.id,fieldId:selected.value.id},{...common,expectedVersion:selected.value.version,reason:field.reason});else await send('D18-API-014',{id:asset.value.id},{...common,fieldCode:field.fieldCode});showField.value=false;selected.value=null;await load();message.value='字段元数据已保存'}
watch(()=>route.query.asset,()=>run(load));onMounted(()=>run(load));
</script><template><section><RouterLink to="/assets">返回资产目录</RouterLink><p role="alert" class="error">{{error}}</p><p role="status">{{message}}</p><template v-if="asset"><h2>{{asset.name}}</h2><p>{{asset.assetCode}} · {{assetStates[asset.status]}} · {{classifications[asset.classification]||asset.classification}}</p><div class="columns"><p>责任人：{{asset.owner?.displayName||'未指定'}} <span v-if="asset.owner?.status==='DISABLED'">（账号已停用）</span></p><p>来源：{{asset.source?.code||'未关联'}} · 字段数：{{fields.length}}</p></div><div class="actions"><button v-if="asset.allowedActions.includes('edit')" @click="openEdit">编辑资产</button><button v-if="asset.allowedActions.includes('registerField')" @click="openField(null)">新增字段</button><button :disabled="busy" @click="run(load)">刷新</button></div><form v-if="showEdit" @submit.prevent="run(save)"><h3>维护资产信息</h3><div class="columns"><label>名称<input v-model="edit.name" required maxlength="128"></label><label>分类<select v-model="edit.classification"><option v-for="(label,key) in classifications" :key="key" :value="key">{{label}}</option></select></label><label>责任人<select v-model="edit.ownerId"><option value="">未指定</option><option v-for="u in owners" :key="u.id" :value="u.id">{{u.displayName}} / {{u.username}}</option></select></label><label>来源<select v-model="edit.sourceId"><option value="">未关联</option><option v-for="s in sources" :key="s.id" :value="s.id">{{s.code}}</option></select></label></div><label>原因<textarea v-model="edit.reason" required maxlength="1000"/></label><button :disabled="busy">保存资产</button><button type="button" @click="showEdit=false">取消</button></form><h3>字段元数据</h3><p>字段代码创建后保持不变；已被标准、规则或问题引用的字段不能直接改变结构。</p><table><thead><tr><th>字段代码 / 名称</th><th>数据类型</th><th>可空</th><th>敏感级别</th><th>标准 / 规则 / 问题关联</th><th>操作</th></tr></thead><tbody><tr v-for="f in fields" :key="f.id"><td>{{f.fieldCode}}<br>{{f.displayName}}</td><td>{{f.dataType}}</td><td>{{f.nullable?'是':'否'}}</td><td>{{sensitivities[f.sensitiveLevel]||f.sensitiveLevel}}</td><td>{{f.standardCount||0}} / {{f.ruleCount||0}} / {{f.issueCount||0}}</td><td><button v-if="canWrite&&asset.status!=='PUBLISHED'" @click="openField(f)">编辑字段</button></td></tr></tbody></table><form v-if="showField" @submit.prevent="run(saveField)"><h3>{{selected?'编辑字段':'新增字段'}}</h3><div class="columns"><label>字段代码<input v-model="field.fieldCode" :readonly="!!selected" required maxlength="64" pattern="[A-Za-z][A-Za-z0-9_.-]*"></label><label>字段名称<input v-model="field.displayName" required maxlength="128"></label><label>数据类型<select v-model="field.dataType" :disabled="!!linked"><option v-for="t in dataTypes" :key="t">{{t}}</option></select></label><label>敏感级别<select v-model="field.sensitiveLevel" :disabled="!!linked"><option v-for="(label,key) in sensitivities" :key="key" :value="key">{{label}}</option></select></label><label class="check"><input v-model="field.nullable" type="checkbox" :disabled="!!linked">允许为空</label></div><label v-if="selected">变更原因<textarea v-model="field.reason" required maxlength="1000"/></label><button :disabled="busy">保存字段</button><button type="button" @click="showField=false">取消</button></form><form v-if="asset.allowedActions.includes('publish')||asset.allowedActions.includes('disable')" @submit.prevent="run(()=>state(asset!.status==='PUBLISHED'?'disable':'publish'))"><h3>{{asset.status==='PUBLISHED'?'停用资产':'发布资产'}}</h3><p v-if="asset.status!=='PUBLISHED'">请确认责任人、分类和字段完整。发布后结构修改受限。</p><p v-else>停用保留既有字段、规则和工单记录，历史闭环仍可追溯。</p><label>操作原因<textarea v-model="reason" required maxlength="1000"/></label><button :disabled="busy">{{asset.status==='PUBLISHED'?'停用':'发布'}}</button></form></template><template v-else><h2>资产元数据</h2><p>请从资产目录选择资产。</p></template></section></template>